    'check_6-4.framemd5': 'Every frame hash equal (ffmpeg framemd5)', 'check_6-2.audio-pcm-identity': 'Audio PCM identity', 'check_6-1.dash-scheme-cbcs': 'DASH scheme is cbcs',
